observations=[]
def fact(suffix,feature,relation,asserted,sources,note,target=None,kind='observed',**meta):
 value={'reference_feature_id':target,'asserted':asserted}
 observations.append({'id':'relationships-'+suffix,'feature_id':feature,'property':relation,'value':value,'evidence_kind':kind,'source_ids':sources,'exposure':'derived' if kind=='inference' else 'already_inspected','note':note,**meta})
def chronology(suffix,feature,sources,note,**value):
 observations.append({'id':'relationships-'+suffix,'feature_id':feature,'property':'chronology','value':{'reference_feature_id':None,'secure_earliest_construction_year':None,'secure_last_accessible_year':None,'dated_accessible_interval':None,**value},'evidence_kind':'published_reconstruction','source_ids':sources,'exposure':'already_inspected','note':note})

