def pred(id,label,relation,subject,object=None,sources=None,missing=None,**extra):
 return {'id':id,'label':label,'relation':relation,'subject':subject,'object':object,'source_ids':sources or ['relationships-text-e60'],'missing_detail':missing or 'No source-controlled observation of this relation is available.','required':True,**extra}
